  /**
    Manages export of an electronics document to various formats.
    Obtain an instance via the exportManager property on Board, Schematic, or Library.
    @experimental
    */
  export class ElectronicsExportManager extends core.Base {
    /**
      Creates export options for exporting this document as an EAGLE 9.6.2 board file (.brd).
      Only valid when called on a Board's export manager.
      @param outputPath Full output file path including file name and extension (e.g. "C:/output/design.brd").
      @returns An ElectronicsExportOptions object configured for .brd export, or null on failure.
      */
    createEagleBrdExportOptions(outputPath: string): ElectronicsExportOptions | null;
    /**
      Creates export options for exporting this document as an EAGLE 9.6.2 schematic file (.sch).
      Only valid when called on a Schematic's export manager.
      @param outputPath Full output file path including file name and extension (e.g. "C:/output/design.sch").
      @returns An ElectronicsExportOptions object configured for .sch export, or null on failure.
      */
    createEagleSchExportOptions(outputPath: string): ElectronicsExportOptions | null;
    /**
      Creates export options for exporting this document as an EAGLE 9.6.2 library file (.lbr).
      Only valid when called on a Library's export manager.
      @param outputPath Full output file path including file name and extension (e.g. "C:/output/mylib.lbr").
      @returns An ElectronicsExportOptions object configured for .lbr export, or null on failure.
      */
    createEagleLbrExportOptions(outputPath: string): ElectronicsExportOptions | null;
    /**
      Executes the export using the provided options. Returns true on success.
      @param options An ElectronicsExportOptions instance obtained from one of the createEagle*ExportOptions methods.
      @returns True if the export succeeded; false otherwise.
      */
    execute(options: ElectronicsExportOptions): boolean;
  }

