  /**
    When a gate is added when placing a multi-gate device (e.g., IC with multiple symbols).
    @experimental
    */
  export const enum GateAddLevels {
      /// Gate must appear whenever any gate from the device is placed; cannot be deleted until all others are removed.
    MustGateAddLevel = 0,
      /// Gate is optional; only added with INVOKE if the device also has Next-gates, or with ADD if the device has only Can and Request gates.
    CanGateAddLevel = 1,
      /// Default: if the device has more than one gate, symbols are placed with this level first.
    NextGateAddLevel = 2,
      /// Gate is added only when explicitly invoked (e.g., power-symbol); not counted for gate naming.
    RequestGateAddLevel = 3,
      /// Like Must, but the gate can be deleted and re-invoked with INVOKE.
    AlwaysGateAddLevel = 4,
  }

  /**
    Gate (logical sub-unit) within a device; references a symbol and defines placement and add behavior.
    @experimental
    */
  export class Gate extends EcadObject {
    /**
      Add level controlling when this gate is placed (Must, Can, Next, Request, or Always).
      */
    readonly addLevel: GateAddLevels;
    /**
      Gate name (e.g., A, B, POWER) within the device.
      */
    readonly name: string;
    /**
      Swap level for pin swapping; gates with the same swap level can be swapped.
      */
    readonly swapLevel: number /*int*/;
    /**
      Symbol (schematic graphic) associated with this gate.
      */
    readonly symbol: Symbol;
    /**
      X coordinate of the gate origin (placement point), in internal units.
      */
    readonly x: number /*int*/;
    /**
      Y coordinate of the gate origin (placement point), in internal units.
      */
    readonly y: number /*int*/;
  }

